				  // 字族那份必须一起清：留着它，用户换主题/换 DSH 字号后新取的快照就永远不会生效。
				  try {
				    const es = document.documentElement.style;
				    for (const t of WE_HOST_TOKENS) es.removeProperty("--we-host-" + t.slice(2));
				    es.removeProperty(WE_HOST_FAMILY_TOKEN);
				  } catch { /* ignore */ }
