				    state.active = false;
				    // 补交定时器也要摘掉：否则拆除之后它仍会醒来（handBack 里的 active 检查兜住交还，
				    // 但留一个活着的定时器是泄漏，也会让台架"拆完还有异步动静"）。
				    if (retryTimer !== null) { clearTimeout(retryTimer); retryTimer = null; state.retrying = false; }
